INSERT INTO Financial (SK_CompanyID, FI_YEAR, FI_QTR, FI_QTR_START_DATE, FI_REVENUE, FI_NET_EARN, FI_BASIC_EPS, FI_DILUT_EPS, FI_MARGIN, FI_INVENTORY, FI_ASSETS, FI_LIABILITY, FI_OUT_BASIC, FI_OUT_DILUT) SELECT (SELECT DC.SK_CompanyID FROM DimCompany AS DC WHERE (DS.CIK = DC.CompanyID OR DS.CoName = DC.Name) AND DC.IsCurrent = TRUE LIMIT 1) AS SK_CompanyID, FI_YEAR, FI_QTR, FI_QTR_START_DATE, FI_REVENUE, FI_NET_EARN, FI_BASIC_EPS, FI_DILUT_EPS, FI_MARGIN, FI_INVENTORY, FI_ASSETS, FI_LIABILITY, FI_OUT_BASIC, FI_OUT_DILUT FROM (SELECT STRPTIME(PTS, '%Y%m%d-%H%M%S') AS PTS, CASE WHEN NOT TRY_CAST(CoNameOrCIK AS BIGINT) IS NULL THEN TRY_CAST(CoNameOrCIK AS INT) END AS CIK, CASE WHEN TRY_CAST(CoNameOrCIK AS BIGINT) IS NULL THEN CoNameOrCIK END AS CoName, TRY_CAST(Year AS INT) AS FI_YEAR, TRY_CAST(Quarter AS INT) AS FI_QTR, CAST(TRY_STRPTIME(QtrStartDate, '%Y%m%d') AS DATE) AS FI_QTR_START_DATE, TRY_CAST(Revenue AS DECIMAL(18, 3)) AS FI_REVENUE, TRY_CAST(Earnings AS DECIMAL(18, 3)) AS FI_NET_EARN, TRY_CAST(EPS AS DECIMAL(18, 3)) AS FI_BASIC_EPS, TRY_CAST(DilutedEPS AS DECIMAL(18, 3)) AS FI_DILUT_EPS, TRY_CAST(Margin AS DECIMAL(18, 3)) AS FI_MARGIN, TRY_CAST(Inventory AS DECIMAL(18, 3)) AS FI_INVENTORY, TRY_CAST(Assets AS DECIMAL(18, 3)) AS FI_ASSETS, TRY_CAST(Liabilities AS DECIMAL(18, 3)) AS FI_LIABILITY, TRY_CAST(ShOut AS DECIMAL(18, 3)) AS FI_OUT_BASIC, TRY_CAST(DilutedShOut AS DECIMAL(18, 3)) AS FI_OUT_DILUT FROM Source.FinwireFIN AS F) AS DS;
